import { useAppStore } from '@/store/appSchema'

// Wails v2 Go bindings - these are auto-generated by Wails
// For now, typed as any since the bindings are generated at build time
declare const window: any

function getGoBinding() {
  return window['go']?.['main']?.['App']
}

// Helper to get current userId from store
function getCurrentUserId(): string {
  const store = useAppStore()
  return store?.getCurrentUserInfo?.userId || 'user1'
}

// Helper to convert Wails Result to HTTP-compatible response
function unwrapResult(result: any) {
  if (result && typeof result === 'object' && 'code' in result) {
    return result
  }
  return result
}

// ---- Image ----

// 路径方案：打开原生文件选择框，立即返回文件路径列表，后台分批解析并推送事件
export async function selectImages() {
  const binding = getGoBinding()
  if (binding) {
    const result = await binding.SelectImages()
    return unwrapResult(result)
  }
  throw new Error('Wails bindings not available')
}

// 监听一批图片解析完成
export function onImagesParsed(callback: (data: any) => void) {
  window.runtime?.EventsOn?.('images-parsed', callback)
}

// 监听解析进度
export function onImagesProgress(callback: (data: any) => void) {
  window.runtime?.EventsOn?.('images-progress', callback)
}

// 监听全部解析完成
export function onImagesDone(callback: (data: any) => void) {
  window.runtime?.EventsOn?.('images-done', callback)
}

// 清理所有图片解析事件监听（组件卸载时调用，防止内存泄漏）
export function offImagesEvents() {
  window.runtime?.EventsOff?.('images-parsed')
  window.runtime?.EventsOff?.('images-progress')
  window.runtime?.EventsOff?.('images-done')
}

// 路径方案：将选中的图片文件导入到用户目录
export async function importImages(data: { images: any[] }) {
  const binding = getGoBinding()
  if (binding) {
    const files = (data.images || []).map((img: any) => ({
      id: img.id,
      name: img.name,
      path: img.path,
    }))
    const result = await binding.ImportImages(getCurrentUserId(), files)
    return unwrapResult(result)
  }
  throw new Error('Wails bindings not available')
}

export async function uploadImages(data: any) {
  const binding = getGoBinding()
  if (binding) {
    const rawImages = data.images || data
    const images = rawImages.map((img: any) => ({
      id: img.id,
      name: img.name,
      url: img.url || '',
      thumbnailUrl: img.thumbnailUrl || '',
    }))
    const result = await binding.UploadImages(getCurrentUserId(), images)
    return unwrapResult(result)
  }
  throw new Error('Wails bindings not available')
}

