// 以模块对象导出，保持与原 HTTP API 相同的调用形态（API.image.xxx / API.schema.xxx）
const image = {
  selectImages,
  importImages,
  uploadImages,
  getImage,
  getImages,
  deleteImages,
  updateImages,
  downloadImage,
  getJPGImage,
  onImagesParsed,
  onImagesProgress,
  onImagesDone,
  offImagesEvents,
}

const schema = {
  getSchema,
  setSchema,
}

const appSchema = {
  getUserInfos,
  getAppSchema,
  setAppSchema,
}

const track = {
  uploadTrack,
  deleteTrack,
  getTrack,
}

const backup = {
  backup: createBackup,
  getBackupSize,
  getBackupList,
  import: importBackup,
  deleteBackup,
}

const user = {
  createUserDir,
  deleteUserDir,
}

// Default export matching original http/index.ts API shape
const API: Record<string, any> = {
  image,
  schema,
  appSchema,
  track,
  backup,
  user,
}

export default API
